/**
 * GET /api/library/tags?trackId= — 查询某首歌的融合标签。
 *
 * 返回全部来源（id3/inferred/llm/user），按优先级排序，并给出**生效视图**
 * （effective：每个 kind 取优先级最高者）—— 前端/编排器展示用它，
 * 溯源审计看原始来源。
 */
import { findSongById } from '@/server/library';
import { getTrackTags, type TrackTag } from '@/server/radio/memory';
import { ok, fail } from '@/server/http';

const PRIORITY: Record<TrackTag['source'], number> = { user: 4, llm: 3, id3: 2, inferred: 1 };

export async function GET(request: Request) {
	const trackId = new URL(request.url).searchParams.get('trackId') ?? '';
	const song = trackId ? await findSongById(trackId) : undefined;
	if (!song) {
		return fail(`track not found: ${trackId}`, 404);
	}
	const tags = getTrackTags(trackId);
	const effective: Record<string, { tag: string; source: string }> = {};
	for (const t of tags) {
		if (!effective[t.kind] || PRIORITY[t.source] > PRIORITY[effective[t.kind].source as TrackTag['source']]) {
			effective[t.kind] = { tag: t.tag, source: t.source };
		}
	}
	return ok({ trackId, song: { title: song.title, artist: song.artist }, tags, effective });
}
